import{_ as e,o,c as d,ae as r}from"./chunks/framework.DQC_QtFV.js";const _=JSON.parse('{"title":"首次启动与扫码登录","description":"","frontmatter":{},"headers":[],"relativePath":"guide/first-start.md","filePath":"guide/first-start.md","lastUpdated":1793162416000}'),a={name:"guide/first-start.md"};function c(s,t,l,i,h,n){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="首次启动与扫码登录" tabindex="-1">首次启动与扫码登录 <a class="header-anchor" href="#首次启动与扫码登录" aria-label="Permalink to &quot;首次启动与扫码登录&quot;">​</a></h1><p>任何镜像里都不包含 QQ。<code>qq</code> 容器在首次启动时安装固定的那个版本，来源必须是下面两者中的 <strong>恰好一个</strong>：</p><table tabindex="0"><thead><tr><th>来源</th><th>怎么给</th></tr></thead><tbody><tr><td>一个下载地址</td><td><code>.env</code> 里设置 <code>QQ_DEB_URL=https://example.com/QQ_3.2.34_260924_amd64_01.deb</code></td></tr><tr><td>一个你已经下载好的 deb</td><td>在 <code>compose.yaml</code> 里把它挂载到 <code>/qq/QQ.deb</code>（取消两行注释），<code>QQ_DEB_URL</code> 留空</td></tr></tbody></table><p>无论选哪一种，容器都会先校验文件的 sha256 与镜像内置的固定值是否一致， <strong>不一致就拒绝安装</strong>，并报出它期望的版本号。安装结果落在 <code>qq_install</code> 卷里， 之后的启动会跳过安装。如果两个来源都没给、或者都给了，容器会说明情况并打印两种 正确的给法，而不是去猜。</p><div class="warning custom-block"><p class="custom-block-title">官方下载地址会返回 403</p><p>官方地址在没有签名的情况下不提供下载。请从镜像站下载文件，自己核对 sha256， 然后要么本地起一个服务（<code>python3 -m http.server</code> 加 <code>QQ_DEB_URL=http://127.0.0.1:8000/&lt;文件&gt;</code>，安装那一步用 <code>network_mode: host</code>）， 要么直接挂载文件。</p></div><h2 id="扫码登录" tabindex="-1">扫码登录 <a class="header-anchor" href="#扫码登录" aria-label="Permalink to &quot;扫码登录&quot;">​</a></h2><ol><li><code>docker compose up -d</code> 之后打开 <a href="http://localhost:8080" target="_blank" rel="noreferrer">http://localhost:8080</a>，用 <code>CONSOLE_PASSWORD</code> 登录。</li><li>面板的 QQ 页（实时画面）显示的就是客户端自己的画面，二维码出现时用手机 App 扫它。 <strong>扫码是手动的，由你完成</strong>——这是唯一必须你亲自动手的登录步骤。</li><li>勾上 自动登录，之后的重启会自己恢复。</li><li>扫码成功后，驱动程序读出数据库密钥，状态行的 <code>db.key</code> 变成 <code>&quot;ok&quot;</code>。</li></ol><p>重启后客户端回到账号页时，驱动程序会自己点一次 登录，保存的会话直接恢复； 面板 QQ 页上的 登录 按钮是这一步的手动重试。只有重新创建过客户端配置 （删掉 <code>qq_profile</code> 卷）才需要再扫一次码。</p><h2 id="密钥提取" tabindex="-1">密钥提取 <a class="header-anchor" href="#密钥提取" aria-label="Permalink to &quot;密钥提取&quot;">​</a></h2><p>数据库密钥让栈能解密客户端自己数据库的一份<strong>私有副本</strong>——消息 id、发送者、 @、引用、图片都从这份副本来，客户端的文件不被补丁、不被替换、也不被写入。 密钥只在你自己的机器上，<code>data/driver/secrets/db_key</code>，权限 0600。</p><p>提取在首次登录时进行一次，之后重启依然有效，不需要再提取。状态行显示 <code>db.key = &quot;missing&quot;</code> 表示还没完成，日志在宿主机的 <code>./logs/keyx.log</code>；显示 <code>&quot;invalid&quot;</code> 表示客户端换过密钥或副本对不上，按 QQ 页上给的步骤重新提取即可。</p><h2 id="出问题时" tabindex="-1">出问题时 <a class="header-anchor" href="#出问题时" aria-label="Permalink to &quot;出问题时&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>含义</th></tr></thead><tbody><tr><td><code>error: no QQ source: set exactly one of ...</code></td><td><code>QQ_DEB_URL</code> 和挂载的 deb 都没给</td></tr><tr><td><code>error: sha256 mismatch: expected ... got ...</code></td><td>这个 deb 不是固定版本，换一个文件</td></tr><tr><td><code>error: both QQ_DEB_URL and the mounted deb ... are set</code></td><td>去掉其中一个</td></tr><tr><td>实时画面一直停在二维码</td><td>这是正常的：扫码登录是手动的，由你完成</td></tr><tr><td>面板页面返回 502</td><td>driver 或 bot 还没起来，看 <code>docker compose logs qq bot</code></td></tr></tbody></table><p>更多见 <a href="./troubleshooting.html">排障</a>。</p>',14)])])}const b=e(a,[["render",c]]);export{_ as __pageData,b as default};
